update public.petition_qualification set details='{"jurisdiction":"Riverton, CA (fictional)","authority":"Sample Election Office (fictional)","measureId":"DEMO-1","officialTitle":"A brighter walk home starts here","officialText":"Evening classes finish after sunset, but the public path from the Eastbridge campus gate to the bus shelter has gaps between lights. Students want to see the route clearly and wait for the bus without standing in the dark. The student path audit illustrates the concern; it is sample evidence, not a measured safety study.\n\nRequested action\nAssess the public path from the Eastbridge campus gate to the bus shelter and publish a pedestrian-lighting plan before winter evening classes.","sourceUrl":"https://example.org/fictional-petition-requirements","statutoryRule":"Fictional demonstration threshold: 1000 accepted signatures. This sample number is not a statement of actual law.","statutoryThreshold":1000,"circulatorDeclaration":"Fictional sample declaration: I personally witnessed each selected signer execute their signature and affirm the accuracy of this collection record. This text is not a jurisdiction-approved affidavit.","notarization":"required"}'::jsonb,status='pending',review_note='Fictional sample requirements. No authority has approved this measure.' where petition_id='20000000-0000-4000-8000-000000000001' and status='missing' and not exists(select 1 from private.signature_receipts where petition_id='20000000-0000-4000-8000-000000000001');
